-- 1. Limpieza: todo lo que cuelga de los usuarios demo, incluidas cuentas creadas en runtime.

create temporary table seed_demo_users on commit drop as
    select id from users
    where id in (
        '10000000-0000-0000-0000-000000000001',
        '10000000-0000-0000-0000-000000000002',
        '10000000-0000-0000-0000-000000000003',
        '10000000-0000-0000-0000-000000000004',
        '10000000-0000-0000-0000-000000000005'
    )
    or email in (
        'admin@minibank.local', 'ana@minibank.local', 'benjamin@minibank.local', 'carlos@minibank.local',
        'dana@minibank.local', 'alice@minibank.local', 'bob@minibank.local'
    )
    or document_number in ('90000001', '90000002', '90000003', '90000004', '90000005');

create temporary table seed_demo_accounts on commit drop as
    select id from accounts
    where user_id in (select id from seed_demo_users)
    or id in (
        '20000000-0000-0000-0000-000000000001',
        '20000000-0000-0000-0000-000000000002',
        '20000000-0000-0000-0000-000000000003',
        '20000000-0000-0000-0000-000000000011',
        '20000000-0000-0000-0000-000000000012',
        '20000000-0000-0000-0000-000000000013',
        '20000000-0000-0000-0000-000000000014'
    )
    or account_number in (
        '000000000001', '000000000002', '000000000003', '000000000011', '000000000012', '000000000013', '000000000014'
    );

create temporary table seed_demo_transfers on commit drop as
    select id from transfers
    where source_account_id in (select id from seed_demo_accounts)
    or target_account_id in (select id from seed_demo_accounts);

delete from audit_logs
where user_id in (select id from seed_demo_users)
or entity_id in (select id from seed_demo_users)
or entity_id in (select id from seed_demo_accounts)
or entity_id in (select id from seed_demo_transfers)
or entity_id in (select id from daily_limits where account_id in (select id from seed_demo_accounts));

delete from movements
where account_id in (select id from seed_demo_accounts)
or transfer_id in (select id from seed_demo_transfers);

delete from transfers
where id in (select id from seed_demo_transfers);

delete from daily_limits
where account_id in (select id from seed_demo_accounts);

delete from accounts
where id in (select id from seed_demo_accounts);

delete from users
where id in (select id from seed_demo_users);

