-- 6. Movimientos

create temporary table seed_transfer_movements (
    id uuid,
    account_id uuid,
    transfer_id uuid,
    type varchar(20),
    amount numeric(19,2),
    balance_after numeric(19,2),
    description varchar(255),
    created_at timestamp with time zone
) on commit drop;

;

create temporary table seed_admin_credit_movements (
    id uuid,
    account_id uuid,
    amount numeric(19,2),
    balance_after numeric(19,2),
    description varchar(255),
    created_at timestamp with time zone
) on commit drop;

;

do $$
begin
    if exists (
        select 1 from information_schema.columns
        where table_schema = current_schema()
        and table_name = 'movements'
        and column_name = 'origin'
    ) then
        execute 'insert into movements (id, account_id, transfer_id, type, origin, amount, balance_after, description, created_at)
                 select id, account_id, transfer_id, type, ''TRANSFER'', amount, balance_after, description, created_at
                 from seed_transfer_movements';
        execute 'insert into movements (id, account_id, transfer_id, type, origin, amount, balance_after, description, created_at)
                 select id, account_id, null, ''CREDIT'', ''ADMIN_CREDIT'', amount, balance_after, description, created_at
                 from seed_admin_credit_movements';
    else
        execute 'insert into movements (id, account_id, transfer_id, type, amount, balance_after, description, created_at)
                 select id, account_id, transfer_id, type, amount, balance_after, description, created_at
                 from seed_transfer_movements';
    end if;
end
$$;

